package com.estradaplay.comunista;
import android.graphics.*;import android.os.*;import android.text.InputType;import android.view.*;import android.widget.*;import androidx.activity.ComponentActivity;import java.util.*;
public final class VehicleCostActivity extends ComponentActivity{private final int BG=Color.rgb(9,5,7),TEXT=Color.rgb(246,238,224),MUTED=Color.rgb(174,151,146),RED=Color.rgb(190,18,38);private LinearLayout p;@Override protected void onCreate(Bundle b){super.onCreate(b);build();}private void build(){ScrollView sv=new ScrollView(this);p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(dp(20),dp(20),dp(20),dp(30));p.setBackgroundColor(BG);sv.addView(p);setContentView(sv);VehicleProfileStore.Profile a=VehicleProfileStore.active(this);p.addView(t("VEÍCULO + ABASTECIMENTO",27,TEXT,true));p.addView(t("Perfis locais, autonomia e consumo real por abastecimentos.",12,MUTED,false));Spinner profiles=new Spinner(this);ArrayList<VehicleProfileStore.Profile> list=VehicleProfileStore.list(this);ArrayList<String> labels=new ArrayList<>();int selected=0;for(int i=0;i<list.size();i++){labels.add(list.get(i).name+" · "+list.get(i).type);if(list.get(i).id.equals(a.id))selected=i;}profiles.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));profiles.setSelection(selected);profiles.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?>p,View v,int pos,long id){if(pos>=0&&pos<list.size()&&!list.get(pos).id.equals(VehicleProfileStore.active(VehicleCostActivity.this).id)){VehicleProfileStore.setActive(VehicleCostActivity.this,list.get(pos).id);build();}}public void onNothingSelected(android.widget.AdapterView<?>p){}});p.addView(profiles,new LinearLayout.LayoutParams(-1,dp(54)));EditText name=e("Nome do veículo",a.name,false),type=e("Tipo: Carro/Moto/Caminhão",a.type,false),km=e("Consumo km/l",fmt(a.kmL),true),price=e("Combustível R$/l",fmt2(a.fuelPrice),true),tank=e("Tanque litros",fmt(a.tankL),true),pct=e("Combustível atual %",fmt(a.fuelPercent),true);for(EditText x:new EditText[]{name,type,km,price,tank,pct})p.addView(x,new LinearLayout.LayoutParams(-1,dp(54)));Button save=b("SALVAR PERFIL",true);p.addView(save,new LinearLayout.LayoutParams(-1,dp(56)));save.setOnClickListener(v->{try{VehicleProfileStore.save(this,new VehicleProfileStore.Profile(a.id,name.getText().toString(),type.getText().toString(),f(km),f(price),f(tank),f(pct)));Toast.makeText(this,"Perfil salvo",Toast.LENGTH_SHORT).show();build();}catch(Throwable e){toast("Confira os valores");}});Button add=b("NOVO PERFIL",false);p.addView(add,new LinearLayout.LayoutParams(-1,dp(50)));add.setOnClickListener(v->{VehicleProfileStore.save(this,new VehicleProfileStore.Profile("v"+System.currentTimeMillis(),"Novo veículo","Carro",10,0,50,50));build();});VehicleProfileStore.Profile now=VehicleProfileStore.active(this);p.addView(t(String.format(Locale.getDefault(),"AUTONOMIA ESTIMADA · %.0f km",now.autonomyKm()),18,Color.rgb(72,212,134),true));double actual=FuelingStore.actualKml(this,now.id);if(actual>0)p.addView(t(String.format(Locale.getDefault(),"CONSUMO REAL RECENTE · %.1f km/l",actual),14,TEXT,true));p.addView(t("REGISTRAR ABASTECIMENTO",14,RED,true));EditText liters=e("Litros abastecidos","",true),total=e("Valor total R$","",true),odo=e("Odômetro km (para consumo real)","",true);p.addView(liters);p.addView(total);p.addView(odo);Button fuel=b("SALVAR ABASTECIMENTO",true);p.addView(fuel,new LinearLayout.LayoutParams(-1,dp(54)));fuel.setOnClickListener(v->{try{FuelingStore.add(this,now.id,f(liters),f(total),f(odo));if(f(liters)>0&&f(total)>0){float unit=(float)(f(total)/f(liters));VehicleProfileStore.save(this,new VehicleProfileStore.Profile(now.id,now.name,now.type,now.kmL,unit,now.tankL,100));}toast("Abastecimento salvo");build();}catch(Throwable e){toast("Confira os valores");}});}private EditText e(String hint,String value,boolean number){EditText x=new EditText(this);x.setHint(hint);x.setText(value);x.setTextColor(TEXT);x.setHintTextColor(MUTED);if(number)x.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);return x;}private Button b(String s,boolean primary){Button x=new Button(this);x.setText(s);x.setTextColor(TEXT);if(primary)x.setBackgroundColor(RED);return x;}private float f(EditText e){String s=e.getText().toString().trim().replace(',','.');return s.isEmpty()?0:Float.parseFloat(s);}private String fmt(float v){return String.format(Locale.US,"%.1f",v);}private String fmt2(float v){return String.format(Locale.US,"%.2f",v);}private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}private TextView t(String v,float s,int c,boolean b){TextView t=new TextView(this);t.setText(v);t.setTextSize(s);t.setTextColor(c);if(b)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}}
